using System;

namespace StdbModule;

public static partial class GermanQuotes
{
    public static class ImmanuelKant
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "So lange also die Eitelkeit der menschlichen Gemüter noch mächtig sein wird, so lange wird sich das Vorurteil auch erhalten, d.i. es wird niemals aufhören.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich werde müde, alle Unaufrichtigkeiten und Widersprechungen auszukramen, die in dieser Schwierigkeit begriffen sind, welche die Leibnizianer uns in der Sache von dem Stoße unelastischer Körper haben machen wollen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Eine Meinung, die einmal im Besitze des Ansehens, und sogar des Vorurteils ist, muß man ohne Ende verfolgen, und aus allen Schlupfwinkeln heraus jagen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Man kann das Weltgebäude nicht ansehen, ohne die trefflichste Anordnung in ihrer Einrichtung, und die sicheren Merkmale der Hand Gottes, in der Vollkommenheit ihrer Beziehungen, zu kennen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der eine Schluß ist ganz richtig: Wenn in der Verfassung der Welt Ordnung und Schönheit hervorleuchten: so ist ein Gott.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Laßt uns ohne Vorurteil urteilen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Handlung des Nachdenkens, und der durch die Vernunft aufgeklärten Vorstellung ist ein mühsamer Zustand, darein die Seele sich nicht ohne Widerstand setzen kann, und aus welchem sie, durch einen natürlichen Hang der körperlichen Maschine, alsbald in den leidenen Zustand zurückfällt, da die sämtlichen Reizungen alle ihre Handlungen bestimmen und regieren.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Einen Einzigen, unbedingt ersten, allgemeinen Grundsatze für alle Wahrheiten gibt es nicht.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wenn, in einer philosophischen Frage, das einstimmige Urteil der Weltweisen ein Wall wäre, über welchen zu schreiten es vor ein gleichsträfliches Verbrechen mit demjenigen, welches Remus beging, müßte gehalten werden, so würde ich mich den Vorwitz wohl vergehen lassen, meinen Einfällen wider das entscheidende Gutachten des ehrwürdigen großen Haufens diejenige Freiheit zu erlauben, die durch nichts weiter als durch die gesunde Vernunft gerechtfertiget ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich wünsche, daß sich meine Leser, auf einen Augenblick in diejenige Verfassung des Gemüts versetzen könnten, welche Cartes vor so unumgänglich nötig zur Erlangung richtiger Einsichten hält, und worin ich mich jetzo befinde, nämlich sich so lange, als diese Betrachtung währet, allen erlernten Begriffen vergessen zu machen, und den Weg zur Wahrheit ohne einen andern Führer als die bloße gesunde Vernunft von selber anzutreten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist aber der Zweck der Logik, nicht zu verwickeln, sondern aufzulösen, nicht verdeckt, sondern augenscheinlich etwas vorzutragen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich gehe noch weiter und sage: es ist ganz was anders, Dinge von einander zu unterscheiden, und den Unterschied der Dinge erkennen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Alles, was in sich selbst widersprechen ist, ist innerlich unmöglich.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Schlechterdings notwendig ist, dessen Gegenteil an sich selbst unmöglich ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es existiert etwas schlechterdings notwendig. Dieses ist einig in seinem Wesen, einfach in seiner Substanz, ein Geist nach seiner Natur, ewig in seiner Dauer, unveränderlich in seiner Beschaffenheit, allgenugsam in Ansehung alles Möglichen und Wirklichen. Es ist ein Gott.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Beweisgrund von dem Dasein Gottes, den wir geben, ist lediglich darauf erbauet, weil etwas möglich ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist eine bekannte Regel der Weltweisen oder vielmehr der gesunden Vernunft überhaupt, daß man ohne die erheblichste Ursache nichts vor ein Wunder, oder eine übernatürliche Begebenheit halten sollte.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Bewunderung über die Abfolge einer Wirkung aus einer Ursache hört auf, so bald ich die Zulänglichkeit der Ursache zu ihr deutlich und leicht einsehe.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist durchaus nötig, daß man sich vom Dasein Gottes überzeuge; es ist aber nicht eben so nötig, daß man es demonstriere.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Objekt der Mathematik ist leicht und einfältig, der Philosophie aber schwer und verwickelt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die philosophischen Erkenntnisse haben mehrenteils das Schicksal der Meinungen, und sind wie die Meteoren, deren Glanz nichts von ihrer Dauer verspricht.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Man irret nicht deswegen, weil der Verstand die Begriffe reglos verknüpfet, sondern, weil man dasjenige Merkmal, was man in einem Dinge nicht wahrnimmt, auch von ihm verneinet, und urteilt, daß dasjenige nicht sei, wessen man sich in einem Dinge nicht bewußt ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Irrtümer entspringen nicht allein daher, weil man gewisse Dinge nicht weiß, sondern weil man sich zu urteilen unternimmt, ob man gleich noch nicht alles weiß, was dazu erfordert wird.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Erhabene rührt, das Schöne reizt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Tiefe Einsamkeit ist erhaben, aber auf eine schreckliche Art.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Verstand ist erhaben, Witz ist schön.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Alle Unterweisung der Jugend hat dieses Beschwerliche an sich, daß man genötigt ist, mit der Einsicht den Jahren vorzueilen, und, ohne die Reife des Verstandes abzuwarten, solche Erkenntnisse erteilen soll, die nach der natürlichen Ordnung nur von einer geübteren und versuchten Vernunft könnten begriffen werden.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Mir ist es so Bedürfnis: Du handle, wie du handeln mußt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Schattenreich ist das Paradies der Phantasten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist bisweilen nötig, den Denker, der auf unrechtem Wege ist, durch die Folgen zu erschrecken, damit er aufmerksamer auf die Grundsätze werde, durch welche er sich gleichsam träumend hat fortführen lassen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Hylozoismus belebt alles, der Materialismus dagegen, wenn er genau erwogen wird, tötet alles.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich habe meine Seele von Vorurteilen gereinigt, ich hab eine jede blinde Ergebenheit vertilgt, welche sich damals einschlich, um manchen eingebildeten Wissen in mir Eingang zu verschaffen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Philosophie, deren Eigendünkel macht, daß sie sich selbst allen eiteln Fragen bloß stellet, siehet sich bloß oft bei dem Anlasse gewisser Erzählungen in schlimmer Verlegenheit, wenn sie entweder an einigem in demselben ungestraft nicht zweifeln oder manches davon unausgelacht nicht glauben darf.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Denn man muss wissen, daß alle Erkenntnis zwei Enden habe, bei denen man sie fassen kann, das eine a priori das andere a posteriori.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "In so ferne ist die Metaphysik eine Wissenschaft von den Grenzen der menschlichen Vernunft, und da ein kleines Land jederzeit viel Grenze hat, überhaupt auch mehr daran liegt, seine Besitzungen wohl zu erkennen und zu behaupten, als blindlings auf Eroberung auszugehen, so ist dieser Nutze der erwähnten Wissenschaft der unbekannteste und zugleich wichtigste, wie er denn auch nur ziemlich spät und nach langer Erfahrung erreichet wird.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wenn die Wissenschaft ihren Kreis durchlaufen hat, so gelanget sie natürlicher Weise zu dem Punkte eines bescheidenen Mißtrauens, und sagt, unwillig über sich selbst, wie viele Dinge gibt es doch, die ich nicht einsehe.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "So wird man einer Seits durch etwas tiefere Nachforschung einsehen lernet: daß die überzeugende und philosophische Einsicht in dem Falle, wovon wir reden, unmöglich sei, so wird man auch anderer Seits bei einem ruhigen und vorurteilfreien Gemüte gestehen müssen, daß sie entbehrlich und unnötig sei.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die wahre Weisheit ist die Begleiterin der Einfalt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wie die Zergliederung beim substantiellen Zusammengesetzten nur in dem Teil ihre Grenze findet, der kein Ganzes ist, d.i. dem Einfachen: so die Verbindung nur in dem Ganzen, das kein Teil ist, d.i. der Welt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Denn alles, was den Gesetzen des Verstandes und der Vernunft widerstreitet, ist freilich unmöglich; was aber, da es Gegenstand der reinen Vernunft ist, lediglich den Gesetzen der anschauenden Erkenntnis nicht unterliegt, ist es nicht ebenso.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ein ganzes aus notwendigen Substanzen ist unmöglich.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ein Ganzes von Substanzen ist demnach ein Ganzes von Zufälligem, und die Welt besteht, ihrem Wesen nach, aus lauter Zufälligem.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Daher, wenn man schon den Dogmatiker mit zehn Beweisen auftreten sieht, da kann man sicher glauben, dass er gar keinen habe.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das: Ich denke, muss alle meine Vorstellungen begleiten können; denn sonst würde etwas in mir vorgestellt werden, was gar nicht gedacht werden könnte, welches eben so viel heißt als: die Vorstellung würde entweder unmöglich, oder wenigstens für mich nichts sein.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das schlechthin Unbedingte wird in der Erfahrung gar nicht angetroffen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Mangel an Urteilskraft ist eigentlich das, was man Dummheit nennt, und einem solchen Gebrechen ist gar nicht abzuhelfen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die allgemeine Logik nun, als vermeintes Organon, heißt Dialektik.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die leichte Taube, indem sie im freien Fluge die Luft teilt, deren Widerstand sie fühlt, könnte die Vorstellung fassen, dass es ihr im luftleeren Raum noch viel besser gelingen werde.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Metaphysik hat zum eigentlichen Zwecke ihrer Nachforschung nur drei Ideen: Gott, Freiheit und Unsterblichkeit.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Philosophie wimmelt von fehlerhaften Definitionen, vornehmlich solche, die zwar wirkliche Elemente zur Definition, aber noch nicht vollständig enthalten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist demütigend für die menschliche Vernunft, dass sie in ihrem reinen Gebrauch nichts ausrichtet, und sogar noch einer Disziplin bedarf, um ihre Ausschweifungen zu bändigen, und die Blendwerke, die ihr daherkommen, zu verhüten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich musste das Wissen aufheben, um zum Glauben Platz zu bekommen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Man kann also zwar richtig sagen: daß die Sinne nicht irren, aber nicht darum, weil sie jederzeit richtig urteilen, sondern weil sie gar nicht urteilen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ohne Sinnlichkeit würde uns kein Gegenstand gegeben, und ohne Verstand keiner gedacht werden. Gedanken ohne Inhalt sind leer, Anschauungen ohne Begriffe sind blind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wir werden, so weit die praktische Vernunft uns zu führen das Recht hat, Handlungen nicht darum für verbindlich halten, weil sie Gebote Gottes sind, sondern sie darum als göttliche Gebote ansehen, weil wir dazu innerlich verbindlich sind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Unser Zeitalter ist das eigentliche Zeitalter der Kritik, der sich alles unterwerfen muss. Religion, durch ihre Heiligkeit, und Gesetzgebung, durch ihre Majestät, wollen sich gemeiniglich derselben entziehen. Aber alsdenn erregen sie gerechten Verdacht wider sich, und können auf unverstellte Achtung nicht Anspruch machen, die die Vernunft nur demjenigen bewilligt, was ihre freie und öffentliche Prüfung hat aushalten können.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Zufällig im reinen Sinne der Kategorie ist das, dessen kontradiktorisches Gegenteil möglich ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Hundert wirkliche Taler enthalten nicht das mindeste mehr als hundert mögliche.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Diese Prolegomena sind nicht zum Gebrauch von Lehrlinge, sondern vor künftige Lehrer, und sollen auch diesen nicht etwa dienen, um den Vortrag einer schon vorhandenen Wissenschaft anzuordnen, sondern um diese Wissenschaft selbst allererst zu erfinden.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist niemals zu spät, vernünftig und weise zu werden; es ist aber jederzeit schwer, wenn die Einsicht spät kommt, sie in Gang zu bringen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich gestehe frei: die Erinnerung des David Hume war eben dasjenige, was mir vor vielen Jahren zuerst den dogmatischen Schlummer unterbrach, und meinen Untersuchungen im Felde der spekulativen Philosophie eine ganz andre Richtung gab.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Alle Metaphysiker sind demnach von ihren Geschäften feierlich und gesetzmäßig so lange suspendiert, bis sie die Frage: Wie sind synthetische Erkenntnisse a priori möglich? genugtuend beantwortet haben.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Dieses Produkt [die kosmologischen Ideen] der reinen Vernunft in ihrem transzendentalen Gebrauch ist das merkwürdigste Phänomen derselben, welches auch unter allen am kräftigsten wirkt, die Philosophie aus ihrem dogmatischen Schlummer zu erwecken, und sie zu den schweren Geschäfte der Kritik der reinen Vernunft selbst zu bewegen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Skeptizism ist uranfänglich aus der Metaphysik und ihrer polizeilosen Dialektik entsprungen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "So viel ist gewiß: wer einmal die Kritik [der reinen Vernunft] gekostet hat, den ekelt auf immer alles dogmatische Gewäsche, womit er vorher aus Not vorlieb nahm, weil seine Vernunft etwas bedurfte, und nichts Besseres zu ihrer Unterhaltung finden konnte. Die Kritik verhält sich zur gewöhnlichen Schulmetaphysik gerade wie Chemie zur Alchemie, oder wie Astronomie zur wahrsagenden Astrologie.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Alle falsche Kunst, alle eitele Weisheit dauert ihre Zeit; denn endlich zerstört sie sich selbst, und die höchste Kultur derselben ist zugleich der Zeitpunkt ihres Unterganges.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Mensch will Eintracht; aber die Natur weiß besser, was für seine Gattung gut ist: sie will Zwietracht.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ohne jene, an sich zwar eben nicht liebenswürdige, Eigenschaft der Ungeselligkeit, woraus der Widerstand entspringt, den jeder bei seinen selbstsüchtigen Anmaßungen notwendig antreffen muß, würde in einem arkadischen Schäferleben, bei vollkommener Eintracht, Genügsamkeit und Wechselliebe, alle Talente auf ewig in ihren Keimen verborgen bleiben: die Menschen gutartig wie Schafe die sie weiden, würden in ihrem Dasein kaum einen größeren Wert verschaffen, als dieses ihr Haustier hat; sie würden das Leere der Schöpfung in Ansehung ihres Zweckes, als vernünftige Natur, nicht ausfüllen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "aus so krummem Holze, als woraus der Mensch gemacht ist, kann nichts ganz Gerades gezimmert werden.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wir sind im hohen Grade durch Kunst und Wissenschaft kultiviert.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Alles Gute aber, das nicht auf moralisch-gute Gesinnung gepropft ist, ist nichts als lauter Schein und schimmerndes Elend.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Aufklärung ist der Ausgang des Menschen aus seiner selbstverschuldeten Unmündigkeit. Unmündigkeit ist das Unvermögen, sich seines Verstandes ohne Leitung eines anderen zu bedienen. Selbstverschuldet ist diese Unmündigkeit, wenn die Ursache derselben nicht am Mangel des Verstandes, sondern der Entschließung und des Mutes liegt, sich seiner ohne Leitung eines anderen zu bedienen. Sapere aude! Habe Mut, dich deines eigenen Verstandes zu bedienen! ist also der Wahlspruch der Aufklärung.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Faulheit und Feigheit sind die Ursachen, warum ein so großer Teil der Menschen, nachdem sie die Natur längst von fremder Leitung frei gesprochen (naturaliter maiorennes), dennoch gerne zeitlebens unmündig bleiben; und warum es anderen so leicht wird, sich zu deren Vormündern aufzuwerfen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Satzungen und Formeln, diese mechanischen Werkzeuge eines vernünftigen Gebrauchs oder vielmehr Mißbrauchs seiner Naturgaben, sind die Fußschellen einer immerwährenden Unmündigkeit.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Daß aber ein Publikum sich selbst aufkläre, ist eher möglich; ja es ist, wenn man ihm nur Freiheit läßt, beinahe unausbleiblich.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ein Mensch kann zwar für eine Person, und auch alsdann nur auf einige Zeit, in dem, was ihm zu wissen obliegt, die Aufklärung aufschieben; aber auf sie Verzicht tun, es sei für seine Person, mehr aber noch für die Nachkommenschaft, heißt die heiligen Rechte der Menschheit verletzen und mit Füßen treten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Was aber nicht einmal ein Volk über sich selbst beschließen darf, das darf noch weniger ein Monarch über das Volk beschließen; denn sein gesetzgebendes Ansehen beruht darauf, daß er den gesammten Volkswillen in dem seinigen vereinigt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wenn denn nun gefragt wird: Leben wir jetzt in einem aufgeklärten Zeitalter? so ist die Antwort: Nein, aber wohl in einem Zeitalter der Aufklärung.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Menschen arbeiten sich von selbst nach und nach aus der Rohigkeit ihrer Naturanlagen heraus, wenn man nur nicht absichtlich künstelt, um sie darin zu erhalten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es ist so bequem, unmündig zu sein. Habe ich ein Buch, das für mich Verstand hat, einen Seelsorger, der für mich Gewissen hat, einen Arzt der für mich die Diät beurtheilt, u. s. w. so brauche ich mich ja nicht selbst zu bemühen. Ich habe nicht nöthig zu denken, wenn ich nur bezahlen kann; andere werden das verdrießliche Geschäft schon für mich übernehmen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "So schädlich ist es, Vorurteile zu pflanzen, weil sie sich zuletzt an denen selbst rächen, die, oder deren Vorgänger, ihre Urheber gewesen sind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Aber Liebe zu Gott als Neigung (pathologische Liebe) ist unmöglich; denn er ist kein Gegenstand der Sinne. Eben dieselbe gegen Menschen ist zwar möglich, kann aber nicht geboten werden; denn es steht in keines Menschen Vermögen, jemanden bloß auf Befehl zu lieben.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Also demütigt das moralische Gesetz unvermeidlich jeden Menschen, indem dieser mit demselben den sinnlichen Hang seiner Natur vergleicht.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Verhalten der Menschen, so lange ihre Natur, wie sie jetzt ist, bliebe, würde also in einem bloßen Mechanismus verwandelt werden, wo, wie im Marionettenspiel, alles gut gestikuliert, aber in den Figuren doch kein Leben anzutreffen sein würde.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Eine jede Handlung ist recht, die oder nach deren Maxime die Freiheit der Willkür eines jeden mit jedermanns Freiheit nach einem allgemeinen Gesetze zusammen bestehen kann.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Handle so, dass du die Menschheit sowohl in deiner Person, als auch in der Person eines jeden anderen jederzeit zugleich als Zweck, niemals bloß als Mittel brauchest.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Hat er aber gemordet, so muss er sterben.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Kinder Handlungen als edele, großemütige, verdienstliche zum Muster aufzustellen, in der Meinung, sie durch Einflößung eines Enhusiasmus für dieselbe einzunehmen, ist vollends zweckwidrig.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Mit einem Worte, das moralische Gesetz verlangt Befolgung aus Pflicht, nicht aus Vorliebe, die man gar nicht voraussetzen kann und soll.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Schriftsteller würden sich manche Irrtümer, manche verlorne Mühe (weil sie auf Blendwerk gestellt war) ersparen, wenn sie sich nur entschließen könnten, mit etwas mehr Offenheit zu Werke zu gehen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Zur inneren Freiheit werden zwei Stücke gefordert: seiner selbst in einem gegebenen Fall Meister und über sich selbst Herr zu sein, d.i. seine Affekte zu zähmen und seine Leidenschaften zu beherrschen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die menschliche Vernunft hat … vorher alle mögliche unrechte Wege versucht, ehe es ihr gelingt, den einzigen wahren zu treffen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Eine bloß empirische Rechtslehre ist (wie der hölzerne Kopf in Phädrus' Fabel) ein Kopf, der schön sein mag, nur schade! daß er kein Gehirn hat.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ich behaupte aber, daß in jeder besonderen Naturlehre nur so viel eigentliche Wissenschaft angetroffen werden könne, als darin Mathematik anzutreffen ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Alles, was uns der Bedürfnis überhebt, zu leeren Räumen unsere Zuflucht zu nehmen, ist wirklicher Gewinn für die Naturwissenschaft.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Übrigens beruht die Möglichkeit der Beschleunigung überhaupt, durch ein fortwährendes Moment derselben, auf dem Gesetze der Trägheit.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Mensch sollte sich aus der Rohigkeit seiner Naturanlagen selbst herausarbeiten, und, indem er sich über sie erhebt, dennoch Acht haben, daß er nicht wider sie verstoße: eine Geschicklichkeit, die er nur spät und nach vielen mißlingenden Versuchen erwarten kann, binnern welcher Zwischenzeit die Menschheit unter den Übeln seufzt, die sie sich aus Unerfahrenheit selbst antut.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Man muss gestehen: daß die größten Übel, welche gesittete Völker drücken, uns vom Kriege, und zwar nicht so sehr von dem, der wirklich oder gewesen ist, als von der nie nachzulassenden und so gar unaufhörlich vermehrten Zurüstung zum künftigen, zugezogen werden.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Und so ist der Ausschlag einer durch Philosophie versuchten ältesten Menschheitsgeschichte: Zufriedenheit mit der Vorsehung und dem Gange menschlicher Dinge im ganzen, der nicht vom Guten anhebend zum Bösen fortgeht, sondern sich vom Schlechten zum Besseren allmählich entwickelt; zu welchem Fortschritte denn ein jeder an seinem Teile, so viel in seinen Kräften steht, beizutragen durch die Natur selbst berufen ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Sich im Denken überhaupt orientieren heißt also: sich, bei der Unzulänglichkeit der objektiven Prinzipien der Vernunft, im Fürwahrhalten nach einem subjektiven Prinzip derselben bestimmen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Freiheit zu denken ist erstlich der bürgerliche Zwang entgegengesetzt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Aufklärung in einzelnen Subjekten durch Erziehung zu gründen, ist also gar leicht; man muß nur früh anfangen, die jungen Köpfe zu dieser Reflexion zu gewöhnen. Ein Zeitalter aber aufzuklären, ist sehr langwierig; denn es finden sich viel äußere Hindernisse, welche jene Erziehungsart teils verbieten, teils erschweren.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Handle so, dass die Maxime deines Willens jederzeit zugleich als Prinzip einer allgemeinen Gesetzgebung gelten könne.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Zwei Dinge erfüllen das Gemüt mit immer neuer und zunehmender Bewunderung und Ehrfurcht, je öfter und anhaltender sich das Nachdenken damit beschäftigt: Der bestirnte Himmel über mir, und das moralische Gesetz in mir.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Darin ist jedermann einig, daß Genie dem Nachahmungsgeiste gänzlich entgegen zu setzen sei. Da nun Lernen nichts als Nachahmen ist, so kann die größte Fähigkeit, Gelehrigkeit (Kapazität), als Gelehrigkeit, doch nicht für Genie gelten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Geschmack ist das Beurteilungsvermögen eines Gegenstandes oder einer Vorstellungsart durch ein Wohlgefallen, oder Mißfallen, ohne alles Interesse. Der Gegenstand eines solchen Wohlgefallens heißt schön.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "In der Religion überhaupt scheint Niederwerfen, Anbetung mit niederhängendem Haupte, mit zerknirschten angstvollen Gebärden und Stimmen, das einzigschickliche Benehmen in Gegenwart der Gottheit zu sein, welches daher auch die meisten Völker angenommen haben und noch beobachten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Organisation aber, als innerer Zweck der Natur, übersteigt unendlich alles Vermögen einer ähnlichen Darstellung durch Kunst.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Schön ist das, was ohne Begriff allgemein gefällt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ungläubisch sein heißt der Maxime nachhängen, Zeugnissen überhaupt nicht zu glauben; ungläubig aber ist der, welcher jenen Vernunftideen, weil es ihnen an theoretischer Begründung ihrer Realität fehlt, darum alle Gültigkeit abspricht. Er urteilt also dogmatisch.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Urteilskraft überhaupt ist das Vermögen, das Besondere als enthalten unter dem Allgemeinen zu denken.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Vernünftige Bewohner anderer Planeten anzunehmen, ist eine Sache der Meinung; denn, wenn wir diesen näher kommen könnten, welches an sich möglich ist, würden wir, ob sie sind, oder nicht sind, durch Erfahrung ausmachen; aber wir werden ihnen niemals so nahe kommen, und so bleibt es beim Meinen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Voltaire sagte, der Himmel habe uns zum Gegengewicht gegen die vielen Mühseligkeiten des Lebens zwei Dinge gegeben: die Hoffnung und den Schlaf. Er hätte noch das Lachen dazu rechnen können; […].", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Was das Leben für uns für einen Wert habe, wenn dieser bloß nach dem geschätzt wird, was man genießt (dem natürlichen Zweck der Summe aller Neigungen, der Glückseligkeit), ist zu entscheiden. Er sinkt unter Null; denn wer wollte wohl das Leben unter denselben Bedingungen, oder auch nach einem neuen, selbst entworfenen (doch dem Naturlaufe gemäßen) Plane, der aber auch bloß auf Genuß gestellt wäre, aufs neue antreten?", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wir können alle Vermögen des menschlichen Gemüts ohne Ausnahme auf die drei zurückführen: das Erkenntnisvermögen, das Gefühl der Lust und Unlust und das Begehrungsvermögen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Erpressungsmittel der Wahrhaftigkeit in äußeren Aussagen, der Eid (tortura spiritualis) wird von einem menschlichen Gerichtshofe nicht bloß für erlaubt, sondern auch für unentbehrlich gehalten: ein trauriger Beweis von der geringen Achtung der Menschen für die Wahrheit, selbst im Tempel der öffentlichen Gerechtigkeit, wo die bloße Idee von ihr schon für sich die größte Achtung einflößen sollte!", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Da nun jede Einschränkung der Freiheit durch die Willkür eines andern Zwang heißt: so folgt, daß die bürgerliche Verfassung ein Verhältnis freier Menschen ist, die (unbeschadet ihrer Freiheit im Ganzen ihrer Verbindung mit andern) doch unter Zwangsgesetzen stehen: weil die Vernunft selbst es so will, und zwar die reine a priori gesetzgebende Vernunft, die auf keinen empirischen Zweck (dergleichen alle unter dem allgemeinen Namen Glückseligkeit begriffen worden) Rücksicht nimmt; als Menschen gar verschieden denken, so daß ihr Wille unter kein gemeinschaftliches Prinzip, folglich auch unter kein äußeres, mit jedermanns Freiheit zusammenstimmendes, Gesetz gebracht werden kann.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Souverän will das Volk nach seinen Begriffen glücklich machen, und wird Despot; das Volk will sich den allgemeinen menschlichen Anspruch auf eigene Glückseligkeit nicht nehmen lassen, und wird Rebell.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die Moral, so fern sie auf dem Begriffe des Menschen, als eines freien, eben darum aber auch sich selbst durch seine Vernunft an unbedingte Gesetze bindenden Wesens, gegründet ist, bedarf weder die Idee eines andern Wesens über ihm, um seine Pflicht zu erkennen, noch einer andern Triebfeder als des Gesetzes selbst, um sie zu beobachten.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Moral also führt unumgänglich zur Religion, wodurch sie sich zur Idee eines machthabenden moralischen Gesetzgebers außer dem Menschen erweitert, in dessen Willen dasjenige Endzweck (der Weltschöpfung) ist, was zugleich Endzweck des Menschen sein kann und soll.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Was aber Wunder überhaupt betrifft, so findet sich, daß vernünftige Menschen den Glauben an dieselbe, dem sie gleichwohl nicht zu entsagen gemeint sind, doch niemals wollen praktische aufkommen lassen; welches so viel sagen will, als: sie glauben zwar, was die Theorie betrifft, daß es dergleichen gebe, in Geschäften aber statuieren sie keine.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Kampf, den ein jeder moralisch wohlgesinnter Mensch, unter der Anführung des guten Prinzips gegen die Anfechtung des bösen, in diesem Leben bestehen muß, kann ihm, wie sehr er sich auch bemüht, doch keinen größern Vorteil verschaffen, als die Befreiung von der Herrschaft des letzteren.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Weh aber dem Gesetzgeber, der eine auf ethische Zwecke gerichtete Verfassung durch Zwang bewirken wollte! Denn er würde dadurch nicht allein gerade das Gegenteil der ethischen bewirken, sondern auch seine politische untergraben und unsicher machen.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Ein heiliges Buch erwirbt sich selbst bei denen (und gerade bei diesen am meisten), die es nicht lesen, wenigstens sich daraus keinen größeren zusammenhängenden Religionsbegriff machen können, die größte Achtung, und alles Vernünfteln verschlägt nicht wider den alle Einwürfe niederschlagenden Machtanspruch: da steht's geschrieben.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Da nun ohne Glauben an ein künftiges Leben gar keine Religion gedacht werden kann, so enthält das Judentum als ein solches, in seiner Reinigkeit genommen, gar keinen Religionsglauben.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Wir können also die allgemeine Kirchengeschichte, sofern sie ein System ausmachen soll, nicht anders, als vom Ursprunge des Christentums anfangen, das, als eine völlige Verlassung des Judentums, worin es entsprang, auf ein ganz neues Prinzip gegründet, eine gänzliche Revolution in Glaubenslehren bewirkte.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das höchste, für Menschen nie völlig erreichbare, Ziel der moralischen Vollkommenheit endlicher Geschöpfe ist aber die Liebe des Gesetzes.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Es gibt keine besondere Pflichten gegen Gott in einer allgemeinen Religion; denn Gott kann von uns nichts empfangen; wir können auf und für ihn nicht wirken.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Die enge Pforte und der schmale Weg, der zum Leben führt, ist der des guten Lebenswandels; die weite Pforte und der breite Weg, den viele wandeln, ist die Kirche.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Der Mohammedianism unterscheidet sich durch Stolz, weil er, statt der Wunder, an den Siegen und der Unterjochung vieler Völker die Bestätigung seines Glaubens findet, und seine Andachtsgebräuche alle von der mutigen Art sind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Tage sind gleichsam Kinder der Zeit, weil der folgende Tag, mit dem was er enthält, das Erzeugnis des vorigen ist.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Ende aller Dinge, die durch der Menschen Hände gehen, ist, selbst bei ihren guten Zwecken, Torheit: das ist, Gebrauch solcher Mittel zu ihren Zwecken, die diesen gerade zuwider sind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Immanuel_Kant", Text = "Das Christentum hat, außer der größten Achtung, welche die Heiligkeit seiner Gesetze unwiderstehlich einflößt, noch etwas Liebenswürdiges in sich.", Author = "Immanuel Kant" },
        };
    }
}